const items = $input.all();
const all = [];
let hasNextPage = false;
let endCursor = null;
const ahora = new Date().toISOString();

for (const item of items) {
  if (item.json && item.json.errors) {
    throw new Error('Shopify GraphQL error: ' + JSON.stringify(item.json.errors));
  }
  const data = item.json && item.json.data && item.json.data.productVariants;
  if (!data) {
    throw new Error('Respuesta inesperada: ' + JSON.stringify(item.json).slice(0, 500));
  }
  hasNextPage = !!(data.pageInfo && data.pageInfo.hasNextPage);
  endCursor = (data.pageInfo && data.pageInfo.endCursor) || null;
  const edges = data.edges || [];
  for (const edge of edges) {
    const v = edge.node;
    if (!v) continue;
    const variantId = (v.id || '').split('/').pop();
    const productId = ((v.product && v.product.id) || '').split('/').pop();
    const inventoryItemId = ((v.inventoryItem && v.inventoryItem.id) || '').split('/').pop();
    if (!variantId) continue;
    const unitCostRaw = v.inventoryItem && v.inventoryItem.unitCost && v.inventoryItem.unitCost.amount;
    all.push({
      shopify_variant_id: variantId,
      shopify_product_id: productId,
      shopify_inventory_item_id: inventoryItemId || null,
      product_title: (v.product && v.product.title) || null,
      variant_title: v.title || null,
      sku: v.sku || null,
      product_status: ((v.product && v.product.status) || '').toLowerCase() || null,
      unit_cost: unitCostRaw ? parseFloat(unitCostRaw) : null,
      unit_cost_currency: (v.inventoryItem && v.inventoryItem.unitCost && v.inventoryItem.unitCost.currencyCode) || null,
      fuente: 'SHOPIFY_GRAPHQL_INVENTORY_ITEM',
      fetched_at: ahora,
      updated_at: ahora
    });
  }
}

return [{ json: { variantes: all, hasNextPage: hasNextPage, cursor: endCursor, count: all.length } }];
